function afficherPopupArticles(){closeAllPopups();const validationChoix=document.getElementById('container-popup-articles');if(!validationChoix){console.error('Conteneur popup introuvable');return}
validationChoix.style.display='flex';validationChoix.innerHTML='';const addPopup=document.createElement('section');addPopup.id='popupValider';addPopup.tabIndex=0;const addLogoCroix=document.createElement('div');addLogoCroix.id='img-logo-croix-article';const logoCroixPicture=document.createElement('picture');const logoCroixSource=document.createElement('source');logoCroixSource.srcset='./assets/webp/supprimer.webp';logoCroixSource.type='image/webp';const addImgLogoCroix=document.createElement('img');addImgLogoCroix.id='croix';addImgLogoCroix.tabIndex=0;addImgLogoCroix.src='./assets/supprimer.png';addImgLogoCroix.alt='Logo Croix';logoCroixPicture.appendChild(logoCroixSource);logoCroixPicture.appendChild(addImgLogoCroix);addImgLogoCroix.addEventListener('click',()=>{validationChoix.style.display='none';validationChoix.innerHTML=''});addImgLogoCroix.addEventListener('keydown',(e)=>{if(e.key==='Enter'){e.preventDefault();addImgLogoCroix.click()}});validationChoix.appendChild(addPopup);addPopup.focus();addPopup.appendChild(addLogoCroix);addLogoCroix.appendChild(logoCroixPicture);const containerDemandeValidation=document.createElement('div');const demandeValidation=document.createElement('p');const memoireArticle=localStorage.getItem('memoireArticle');demandeValidation.innerHTML=`Voulez-vous ajouter  ${memoireArticle} à votre panier&nbsp;?`;demandeValidation.style.paddingBottom='20px';const btnValidation=document.createElement('button');btnValidation.id='btn-etape-suivante';btnValidation.textContent='Valider';btnValidation.addEventListener('click',()=>{ajouterArticlePanier();validationChoix.style.display='none';validationChoix.innerHTML=''});containerDemandeValidation.appendChild(demandeValidation);containerDemandeValidation.appendChild(btnValidation);addPopup.appendChild(containerDemandeValidation)}
function afficherPopupMessageAPI(texte){closeAllPopups();const messageValidation=document.getElementById('succes-commande');const modeCommande=localStorage.getItem('mode');if(!messageValidation){console.error('Conteneur popup introuvable');return}
messageValidation.style.display='flex';messageValidation.innerHTML='';const addPopup=document.createElement('section');addPopup.id='popupValider';addPopup.tabIndex=0;messageValidation.appendChild(addPopup);addPopup.focus();const containerDemandeValidation=document.createElement('div');containerDemandeValidation.classList.add('container-validation');const demandeValidation=document.createElement('p');demandeValidation.innerHTML=texte;demandeValidation.style.paddingBottom='20px';const btnValidation=document.createElement('button');btnValidation.id='btn-etape-suivante-API';btnValidation.textContent='OK';btnValidation.addEventListener('click',()=>{if(modeCommande==='sur place'){window.location.href='chevalet.html'}else if(modeCommande==='à emporter'){window.location.href='remerciements.html'}});containerDemandeValidation.appendChild(demandeValidation);containerDemandeValidation.appendChild(btnValidation);addPopup.appendChild(containerDemandeValidation)}
function afficherPopupMessageAPISucces(){afficherPopupMessageAPI('Votre commande a été validée avec succès&nbsp;!')}
function afficherPopupMessageAPIErreur(){afficherPopupMessageAPI("Une erreur s'est produite&nbsp;!")}
function closeAllPopups(){document.getElementById('container-popup-articles').style.display='none';document.getElementById('succes-commande').style.display='none'}